// Deep reviewed and polished by a human on 2026-08-10.

import js from "@eslint/js"
import importPlugin from "eslint-plugin-import"
import unicorn from "eslint-plugin-unicorn"
import tseslint from "typescript-eslint"
import { ambientAuthority, invariants, swallowedCause, uninstalledSafety } from "../../../../eslint.invariants.js"
import { jsdocConvention } from "../../../../eslint.jsdoc.js"

export default tseslint.config(
  { ignores: ["**/dist", "**/coverage"] },
  js.configs.recommended,
  importPlugin.flatConfigs.recommended,
  importPlugin.flatConfigs.typescript,
  {
    files: ["src/**/*.ts"],
    extends: [tseslint.configs.recommended],
    languageOptions: { parserOptions: { projectService: true, tsconfigRootDir: import.meta.dirname } },
    settings: { "import/resolver": { typescript: { project: ["./tsconfig.json"] } } },
    plugins: { unicorn },
    rules: {
      "@typescript-eslint/consistent-type-imports": "error",
      "@typescript-eslint/no-explicit-any": "off",
      "import/no-duplicates": "error",
      "no-console": "error"
    }
  },
  {
    files: ["examples/**/*.ts"],
    extends: [tseslint.configs.recommended],
    languageOptions: {
      parserOptions: { project: "./tsconfig.test.json", tsconfigRootDir: import.meta.dirname }
    },
    settings: { "import/resolver": { typescript: { project: ["./tsconfig.test.json"] } } },
    rules: { "import/no-duplicates": "error", "no-console": "error" }
  },
  ...jsdocConvention,
  ...invariants(uninstalledSafety, swallowedCause, ambientAuthority)
)

{
  "name": "@smthrs/canonical",
  "type": "module",
  "version": "1.0.0-rc.16",
  "license": "MIT",
  "smthrs": {
    "group": "engine"
  },
  "description": "RFC 8785 canonical JSON as an Effect Schema",
  "homepage": "https://github.com/smithersai/smithers",
  "repository": {
    "type": "git",
    "url": "https://github.com/smithersai/smithers.git",
    "directory": "packages/smithers/flows/canonical"
  },
  "engines": {
    "node": ">=22.19.0"
  },
  "sideEffects": [],
  "exports": {
    "./package.json": "./package.json",
    ".": "./src/index.ts",
    "./internal/*": null,
    "./*/index": null,
    "./Canonical": "./src/Canonical.ts",
    "./index": "./src/index.ts",
    "./Record": "./src/Record.ts",
    "./BoundedJson": "./src/BoundedJson.ts",
    "./IssuePath": "./src/IssuePath.ts",
    "./ReadonlyMap": "./src/ReadonlyMap.ts",
    "./Serializer": "./src/Serializer.ts"
  },
  "files": [
    "src/**/*.ts",
    "dist/**/*",
    "LICENSE",
    "README.md",
    "docs/",
    "examples/"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true,
    "tag": "next",
    "exports": {
      "./package.json": "./package.json",
      ".": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      },
      "./internal/*": null,
      "./*/index": null,
      "./Canonical": {
        "import": {
          "types": "./dist/esm/Canonical.d.ts",
          "default": "./dist/esm/Canonical.js"
        },
        "require": {
          "types": "./dist/cjs/Canonical.d.ts",
          "default": "./dist/cjs/Canonical.js"
        }
      },
      "./index": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      },
      "./Record": {
        "import": {
          "types": "./dist/esm/Record.d.ts",
          "default": "./dist/esm/Record.js"
        },
        "require": {
          "types": "./dist/cjs/Record.d.ts",
          "default": "./dist/cjs/Record.js"
        }
      },
      "./BoundedJson": {
        "import": {
          "types": "./dist/esm/BoundedJson.d.ts",
          "default": "./dist/esm/BoundedJson.js"
        },
        "require": {
          "types": "./dist/cjs/BoundedJson.d.ts",
          "default": "./dist/cjs/BoundedJson.js"
        }
      },
      "./IssuePath": {
        "import": {
          "types": "./dist/esm/IssuePath.d.ts",
          "default": "./dist/esm/IssuePath.js"
        },
        "require": {
          "types": "./dist/cjs/IssuePath.d.ts",
          "default": "./dist/cjs/IssuePath.js"
        }
      },
      "./ReadonlyMap": {
        "import": {
          "types": "./dist/esm/ReadonlyMap.d.ts",
          "default": "./dist/esm/ReadonlyMap.js"
        },
        "require": {
          "types": "./dist/cjs/ReadonlyMap.d.ts",
          "default": "./dist/cjs/ReadonlyMap.js"
        }
      },
      "./Serializer": {
        "import": {
          "types": "./dist/esm/Serializer.d.ts",
          "default": "./dist/esm/Serializer.js"
        },
        "require": {
          "types": "./dist/cjs/Serializer.d.ts",
          "default": "./dist/cjs/Serializer.js"
        }
      }
    }
  },
  "scripts": {
    "lint": "eslint src examples --max-warnings=0 && dprint check",
    "format": "dprint fmt",
    "build": "node scripts/build.mjs",
    "check": "vibelang -b tsconfig.json && vibelang -p tsconfig.test.json --noEmit",
    "circular": "node ../../../repo-targets/scripts/circular.mjs",
    "pretest": "pnpm run test:dist",
    "test": "vitest",
    "test:dist": "pnpm run build && node --test test/dist-smoke.mjs",
    "coverage": "vitest --coverage"
  },
  "devDependencies": {
    "@effect/language-service": "0.87.2",
    "@effect/vitest": "4.0.5",
    "@eslint/js": "9.39.5",
    "@types/node": "26.4.1",
    "dprint": "0.57.1",
    "effect": "4.0.5",
    "esbuild": "0.28.2",
    "eslint": "9.39.5",
    "eslint-import-resolver-typescript": "4.4.5",
    "eslint-plugin-import": "2.32.0",
    "eslint-plugin-jsdoc": "64.3.4",
    "eslint-plugin-unicorn": "65.0.0",
    "madge": "8.0.0",
    "typescript": "5.9.3",
    "typescript-eslint": "8.69.0",
    "vibelang": "0.0.8",
    "vibelang-vite": "0.0.8",
    "vitest": "5.0.0",
    "fast-check": "4.9.0"
  },
  "peerDependencies": {
    "effect": "4.0.5"
  }
}

import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import vibelang from "vibelang-vite"
import { configDefaults, defineConfig } from "vitest/config"

export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.test.json" })],
  test: {
    globalSetup: [
      fileURLToPath(new URL("../../../repo-targets/test-utils/coverage-teardown.mjs", import.meta.url)),
      fileURLToPath(new URL("../../../repo-targets/test-utils/test-process-environment.mjs", import.meta.url))
    ],
    include: [...configDefaults.include, "**/*.{test,spec}.vibe"],
    environment: "node",
    testTimeout: 30_000,
    hookTimeout: 30_000,
    coverage: {
      enabled: true,
      provider: "v8",
      reportsDirectory: join(tmpdir(), `flows-canonical-coverage-${process.pid}`),
      include: ["src/**/*.{ts,vibe}"],
      thresholds: { branches: 100, functions: 100, lines: 100, statements: 100 }
    }
  }
})
